package android.hardware.camera2;public class CameraManager {public final CameraDevice[] devices={new CameraDevice(),new CameraDevice()};public int next;public boolean deferOpen;public CameraCharacteristics getCameraCharacteristics(String id){return new CameraCharacteristics();}public void openCamera(String id,CameraDevice.StateCallback cb,android.os.Handler h){CameraDevice d=devices[next++];d.callback=cb;if(!deferOpen)cb.onOpened(d);}public void opened(int i){devices[i].callback.onOpened(devices[i]);}}